mapper.select:
select t.machine_id,t.machine_id machineId,t.contact_id,t.contact_id contactId,t.create_time,t.create_time
createTime,t.remark,t.status_cd,t.status_cd statusCd,t.platform_id,t.platform_id
platformId,t.community_id,t.community_id communityId,t.device_id,t.device_id deviceId,cd.calling_type callingType,
cd.device_name deviceName,cd.calling_num callingNum,cp.platform_name platformName,cp.ip_addr ipAddr,cp.`port` port
from calling_contact t
left join calling_platform cp on t.platform_id = cp.platform_id and cp.status_cd = '0'
left join calling_device cd on t.device_id = cd.device_id and cd.status_cd = '0'
where 1 =1

    and cd.device_name = #{deviceName}


    and cd.calling_num= #{callingNum}


    and cp.platform_name= #{platformName}


    and t.machine_id= #{machineId}


    and t.contact_id= #{contactId}


    and t.create_time= #{createTime}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.platform_id= #{platformId}


    and t.community_id= #{communityId}


    and t.device_id= #{deviceId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update calling_contact t set t.status_cd = #{statusCd}

    , t.machine_id= #{machineId}


    , t.create_time= #{createTime}


    , t.remark= #{remark}


    , t.platform_id= #{platformId}


    , t.community_id= #{communityId}


    , t.device_id= #{deviceId}

where 1=1

    and t.contact_id= #{contactId}

mapper.select:
select count(1) count
from calling_contact t
left join calling_platform cp on t.platform_id = cp.platform_id and cp.status_cd = '0'
left join calling_device cd on t.device_id = cd.device_id and cd.status_cd = '0'
where 1 =1

    and cd.device_name = #{deviceName}


    and cd.calling_num= #{callingNum}


    and cp.platform_name= #{platformName}


    and t.machine_id= #{machineId}


    and t.contact_id= #{contactId}


    and t.create_time= #{createTime}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.platform_id= #{platformId}


    and t.community_id= #{communityId}


    and t.device_id= #{deviceId}
